public static int findNthLeapYear(int Y, int N) {
    // Helper function to determine if a year is a leap year
    boolean isLeapYear(int year) {
        if (year % 400 == 0) return true;
        if (year % 100 == 0) return false;
        if (year % 4 == 0) return true;
        return false;
    }

    // Find the Nth leap year after the start year
    int leapYearCount = 0;
    for (int year = Y; year <= Integer.MAX_VALUE; year++) {
        if (isLeapYear(year)) {
            leapYearCount++;
            if (leapYearCount == N) {
                return year;
            }
        }
    }

    // If not enough leap years are found, return -1 or handle as needed
    throw new IllegalArgumentException("Not enough leap years found for the given N.");
}
