import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PermuteAll {
    public List<List<Integer>> permute(int[] nums) {
        // Initialize the result list to hold the permutations
        List<List<Integer>> result = new ArrayList<>();
        // Helper function to rotate subarray from start to end
        void rotate(int[] arr, int start, int end) {
            while (start < end) {
                int temp = arr[start];
                arr[start] = arr[end];
                arr[end] = temp;
                start++;
                end--;
            }
        }
        // Helper function to backtrack and build permutations
        void backTrack(int[] nums, int start, int end, List<List<Integer>> result) {
            if (start == end) {
                // RECURSIVE BASE CASE: If we have reached the end of the array
                List<Integer> permutation = new ArrayList<>();
                for (int num : nums) {
                    permutation.add(num);
                }
                result.add(permutation);
                return;
            }
            for (int i = start; i <= end; i++) {
                if (i > start && nums[i] == nums[i - 1]) {
                    continue; // Skip duplicate numbers
                }
                // Place the current number at the beginning
                swap(nums, start, i);
                // Recur for the remaining numbers
                backTrack(nums, start + 1, end, result);
                // Backtrack: restore the array to its original state
                swap(nums, start, i);
            }
        }
        // Helper function to swap two elements in an array
        void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
        // Sort the array to handle duplicates before permutation
        Arrays.sort(nums);
        backTrack(nums, 0, nums.length - 1, result);
        return result;
    }
}
