import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public List<List<Integer>> permute(int[] nums) {
        if (nums == null || nums.length == 0) {
            return Arrays.asList(new ArrayList<>());
        }

        List<List<Integer>> result = new ArrayList<>();
        permuteRecursive(nums, 0, result);
        return result;
    }

    private void permuteRecursive(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length - 1) {
            result.add(Arrays.asList(nums));
            return;
        }

        for (int i = start; i < nums.length; i++) {
            // Swap the current element with the start element
            int temp = nums[start];
            nums[start] = nums[i];
            nums[i] = temp;

            // Recur for the rest of the array
            permuteRecursive(nums, start + 1, result);

            // Swap back the current element to restore the original array
            temp = nums[start];
            nums[start] = nums[i];
            nums[i] = temp;
        }
    }
}
