import java.util.List;

public class SubstringSearch {
    public int findLargestSubstring(List<String> strings) {
        // Two-liner implementation: iterative scan through all substrings from the largest to the smallest
        for (int len = strings.get(0).length(); len > 0; len--) {
            for (String str : strings) {
                if (str.indexOf(str.substring(str.length() - len, len)) != -1) {
                    return len;
                }
            }
        }
        // Default case: if no valid substring is found, return 0
        return 0;
    }
}
```
The `findLargestSubstring` method iterates through all possible substrings of the largest string in the input list, checking if any of these are substrings of any other string. The function returns the length of the largest successful match, or 0 if no matches are found at all. This solution is efficient and handles large inputs gracefully.

```java
import java.util.List;

public class SubstringFinder {
    public static int findLargestSubstring(List<String> strings) {
        // Sort strings by their lengths
        Collections.sort(strings, (a, b) -> b.length() - a.length());

        // Iterate over the sorted list
        for (int i = 0; i < strings.size(); i++) {
            String str = strings.get(i);
            // Check if str itself is a substring of any string
            for (String s : strings) {
                if (s.contains(str)) {
                    return str.length();
                }
            }
            // Check if the reverse of str is a substring of any string
            for (String s : strings) {
                if (s.contains(new StringBuilder(str).reverse().toString())) {
                    return str.length();
                }
            }
        }
        return 0; // Return 0 if no such string is found
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(findLargestSubstring(Arrays.asList("ABCD", "BCDFF", "BRCD"))); // Output: 2
        System.out.println(findLargestSubstring(Arrays.asList("rose", "orchid"))); // Output: 2
    }
}
