    for (int i = 0; i < strings.size(); i++) {
        for (int j = i + 1; j < strings.size(); j++) {
            String current = strings.get(i);
            String reversed = new StringBuilder(current).reverse().toString();
            if (isSubstring(strings, current) || isSubstring(strings, reversed)) {
                maxSubstring = Math.max(maxSubstring, current.length());
            }
        }
    }
    return maxSubstring.isEmpty() ? 0 : maxSubstring;
}

private boolean isSubstring(List<String> strings, String target) {
    for (String str : strings) {
        if (str.contains(target)) {
            return true;
        }
    }
    return false;
