import java.util.List;
import java.util.HashSet;

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    String largestSubstring = "";
    // Using a HashSet for efficient lookups
    HashSet<String> set = new HashSet<>(strings);

    // Check each string for all possible substrings
    for (String str : strings) {
        for (int i = 1; i <= str.length(); i++) {
            String prefix = str.substring(0, i);

            /*
             * Calculate the reverse of the prefix and check if it's in the set
             * This makes the function work for case-sensitive inputs directly
             */
            String reversePrefix = new StringBuilder(prefix).reverse().toString();
            if (set.contains(reversePrefix)) {
                if (reversePrefix.length() > largestSubstring.length()) {
                    largestSubstring = reversePrefix;
                }
            }
        }
    }

    // Check if the original string has the largest substring, if not update largestSubstring
    for (String str : strings) {
        if (str.length() >= largestSubstring.length() && set.contains(str)) {
            largestSubstring = str;
        }
    }

    return largestSubstring.length();
}
