    public static int countOilDeposits(char[][] grid) {
        int count = 0;
        boolean[][] visited = new boolean[grid.length][grid[0].length];

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (grid[i][j] == '@' && !visited[i][j]) {
                    exploreDeposits(grid, i, j, visited);
                    count++;
                }
            }
        }
        return count;
    }

    private static void exploreDeposits(char[][] grid, int x, int y, boolean[][] visited) {
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || visited[x][y]) {
            return;
        }
        if (grid[x][y] != '@') {
            return;
        }

        visited[x][y] = true;
        exploreDeposits(grid, x, y + 1, visited);
        exploreDeposits(grid, x, y - 1, visited);
        exploreDeposits(grid, x + 1, y, visited);
        exploreDeposits(grid, x - 1, y, visited);
    }
}
