public static int countOilDeposits(char[][] grid) {
    int count = 0; // Initialize the count of oil deposits
    boolean[][] visited = new boolean[grid.length][grid[0].length]; // Mark visited positions

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) { // Check for an oil pocket and mark as visited
                dfs(grid, i, j, visited);
                count++; // Increment the count if an oil pocket is found
            }
        }
    }
    return count;
}

private static void dfs(char[][] grid, int i, int j, boolean[][] visited) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || visited[i][j] || grid[i][j] != '@') {
        return; // Base case: out of bounds, visited, or not an oil pocket
    }
    visited[i][j] = true; // Mark the current position as visited
    // Recursively visit all four adjacent positions
    dfs(grid, i + 1, j, visited);
    dfs(grid, i - 1, j, visited);
    dfs(grid, i, j + 1, visited);
    dfs(grid, i, j - 1, visited);
}
