import java.util.HashSet;
import java.util.Set;

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0; // No oil deposits if the grid is empty or improperly nested
    }

    int count = 0;
    Set<String> visited = new HashSet<>();

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@' && !visited.contains(indexToString(i, j))) {
                count++;
                visited.add(indexToString(i, j));
                expandDeposits(grid, i, j, visited);
            }
        }
    }

    return count;
}

private void expandDeposits(char[][] grid, int i, int j, Set<String> visited) {
    final int[] dx = {-1, 1, 0, 0};
    final int[] dy = {0, 0, -1, 1};

    for (int k = 0; k < 4; k++) {
        int newX = i + dx[k];
        int newY = j + dy[k];

        if (newX >= 0 && newX < grid.length && newY >= 0 && newY < grid[newX].length && grid[newX][newY] == '@' && 
            !visited.contains(indexToString(newX, newY))) {
            visited.add(indexToString(newX, newY));
            expandDeposits(grid, newX, newY, visited);
        }
    }
}

private String indexToString(int x, int y) {
    return x + "x" + y;
}
