/**
 * Determines if it is possible to travel from the starting n-tersection to the ending n-tersection.
 * Paths are represented as a matrix where paths[i][j] indicates there is a path from point i to point j.
 * 
 * @param n      the size of the n-teresting space
 * @param start  the starting n-tersection coordinates
 * @param end    the ending n-tersection coordinates
 * @param paths   paths between adjacent n-tersections
 * @return a string indicating whether travel is possible or not
 */
public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || checkInvalidInput(start, end, paths)) return "invalid input";
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) return "can be travelled";

        for (int[] path : paths) {
            int newX = current[0] + path[0];
            int newY = current[1] + path[1];

            if (isValidMove(newX, newY, n) && !visited[newX][newY]) {
                visited[newX][newY] = true;
                queue.offer(new int[]{newX, newY});
            }
        }
    }

    return "cannot be travelled";
}

private static boolean isValidMove(int x, int y, int n) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

private static boolean checkInvalidInput(int[] start, int[] end, int[][] paths) {
    return start == null || end == null || paths == null || paths.length == 0;
}
