public class MazeTraveler {

    public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        if (n <= 0 || start == null || end == null || paths == null) {
            throw new IllegalArgumentException("Invalid input values");
        }

        // Define the n-tersecting space
        String[][] space = new String[n][n];

        // Populate the space with possible paths
        for (int i = 0; i < paths.length; i++) {
            int[] path = paths[i];
            space[path[0]][path[1]] = " traveled";
        }

        // Check the starting and ending points
        if (space[start[0]][start[1]] != "traveled" || space[end[0]][end[1]] == "traveled") {
            return "cannot be travelled";
        }

        // Check if there is a path from start to end
        if (!hasPath(space, n, start, end)) {
            return "cannot be travelled";
        }

        return "can be travelled";
    }

    private static boolean hasPath(String[][] space, int n, int[] start, int[] end) {
        Set<String> visited = new HashSet<>();
        return dfs(space, n, start, end, visited);
    }

    private static boolean dfs(String[][] space, int n, int[] start, int[] end, Set<String> visited) {
        if (visited.contains(String.valueOf(start[0]) + "," + String.valueOf(start[1]))) {
            return false;
        }
        visited.add(String.valueOf(start[0]) + "," + String.valueOf(start[1]));

        if (space[start[0]][start[1]].equals("traveled") && start[0] == end[0] && start[1] == end[1]) {
            return true;
        }

        for (int[] direction : new int[][] { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } }) {
            int x = start[0] + direction[0];
            int y = start[1] + direction[1];

            if (x >= 0 && x < n && y >= 0 && y < n) {
                if (hasPath(space, n, new int[] { x, y }, end, visited)) {
                    return true;
                }
            }
        }

        return false;
    }
}
