public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Invalid input handling
    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input");
    }
    if (start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Start and end coordinates must be 2D arrays");
    }
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        throw new IllegalArgumentException("Coordinates must be within the range of the n-teresting space");
    }

    // Check if the start and end points are the same
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build an Eulerian cycle for the graph
    List<int[]> eCycle = new ArrayList<>();
    for (int[] path : paths) {
        eCycle.add(path);
        eCycle.add(new int[] {path[1], path[0]}); // Add the reverse edge
    }

    // Check if the Eulerian cycle forms a Hamiltonian cycle
    int[] currNode = start;
    for (int i = 0; i < eCycle.size(); i++) {
        int[] nextStep = eCycle.get(i);
        int nextNode = nextStep[0];
        if (nextNode == currNode) {
            // Here, we can stop checking the path and move to the next node
            // This allows us to find any starting point that leads to the end node
            return "can be travelled";
        } else {
            currNode = nextNode;
        }
    }

    // If no Hamiltonian cycle is found
    return "cannot be travelled";
}
