public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int sumOfLengths = word1.length() + word2.length();
    double approximateValue = ((double) commonLetters) / sumOfLengths;
    BigInteger numerator = BigInteger.valueOf(commonLetters);
    BigInteger denominator = BigInteger.valueOf(sumOfLengths);
    BigInteger gcd = numerator.gcd(denominator);
    numerator = numerator.divide(gcd);
    denominator = denominator.divide(gcd);
    Rational result = new Rational(numerator, denominator);
    return "appx(" + word1 + ", " + word2 + ") = " + result.toString();
}

public static class Rational {
    private final BigInteger numerator;
    private final BigInteger denominator;

    public Rational(BigInteger numerator, BigInteger denominator) {
        this.numerator = numerator;
        this.denominator = denominator;
    }

    @Override
    public String toString() {
        return numerator + "/" + denominator;
    }

    public static Rational toRational(double value) {
        BigInteger numerator = BigInteger.valueOf((long) value);
        BigInteger denominator = BigInteger.ONE;
        while (value != 0 && numerator.compareTo(denominator) < 0) {
            value *= 10;
            numerator = BigInteger.valueOf((long) value % 10);
            denominator *= 10;
        }
        return new Rational(numerator, denominator);
    }

    public double getValue() {
        return numerator.longValue() / denominator.doubleValue();
    }

    public int getIntegerValue() {
        return numerator.intValue();
    }

    public static Rational add(Rational a, Rational b) {
        BigInteger newNumerator = a.numerator.multiply(b.denominator).add(b.numerator.multiply(a.denominator));
        BigInteger newDenominator = a.denominator.multiply(b.denominator);
        return new Rational(newNumerator, newDenominator);
    }

    public static Rational subtract(Rational a, Rational b) {
        BigInteger newNumerator = a.numerator.multiply(b.denominator).subtract(b.numerator.multiply(a.denominator));
        BigInteger newDenominator = a.denominator.multiply(b.denominator);
        return new Rational(newNumerator, newDenominator);
    }

    public static Rational multiply(Rational a, Rational b) {
        BigInteger newNumerator = a.numerator.multiply(b.numerator);
        BigInteger newDenominator = a.denominator.multiply(b.denominator);
        return new Rational(newNumerator, newDenominator);
    }

    public static Rational divide(Rational a, Rational b) {
        BigInteger newNumerator = a.numerator.multiply(b.denominator);
        BigInteger newDenominator = a.denominator.multiply(b.numerator);
        return new Rational(newNumerator, newDenominator);
    }
}
