public class TrimMean {
    public double trimMean(int[] arr) {
        // Sort the array to easily access the smallest and largest 5%
        Arrays.sort(arr);

        // Calculate 5% of the array size
        int removeCount = arr.length / 20;

        // Use a max heap to keep track of the largest 5%
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>();
        for (int i = arr.length - removeCount; i < arr.length; i++) {
            maxHeap.offer(arr[i]);
        }

        // Use a min heap to keep track of the smallest 5%
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int i = 0; i < arr.length - (removeCount * 2); i++) {
            minHeap.offer(arr[i]);
        }

        // Calculate the sum of the remaining elements
        double sum = 0;
        for (int i = arr.length - (removeCount * 2); i < arr.length - removeCount; i++) {
            sum += minHeap.poll();
        }
        for (int i = 0; i < removeCount; i++) {
            sum += maxHeap.poll();
        }

        // Calculate the mean
        return sum / (arr.length - (removeCount * 2));
    }
}
