 * Trim the mean of the remaining elements after removing the smallest 5% and largest 5%.
 * @param arr the input array of integers
 * @return the mean of the remaining elements, with an error within 10^-5
 */
public double trimMean(int[] arr) {
    quickSort(arr, 0, arr.length - 1);
    int size = arr.length - (arr.length * 0.1 * 2);
    double sum = 0;
    for (int i = size; i <  arr.length - size; i++) {
        sum += arr[i];
    }
    return sum / ((arr.length - (arr.length * 0.1 * 2)) * 2);
}

private void quickSort(int[] arr, int left, int right) {
    if (left >= right) return;
    int pivotIndex = particion(arr, left, right);
    quickSort(arr, left, pivotIndex - 1);
    quickSort(arr, pivotIndex + 1, right);
}

private int particion(int[] arr, int left, int right) {
    int pivot = arr[right];
    int i = left - 1;
    for (int j = left; j < right; j++) {
        if (arr[j] < pivot) {
            i++;
            swap(arr, i, j);
        }
    }
    swap(arr, i + 1, right);
    return i + 1;
}

private void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}
