    // Check if the array length is odd and should be divided by k
    if ((arr.length & 1) != 0 && k != 1) {
        return false;
    }

    // Count of numbers that leave a remainder of 0 when divided by k
    int[] remainders = new int[k];
    for (int num : arr) {
        remainders[num % k]++;
    }

    // If there's an odd number of numbers with remainders of 0, return true
    if (remainders[0] % 2 != 0) {
        return false;
    }

    // If there's exactly one number with a remainder of k/2, return true
    if (remainders[k / 2] != 0 && k % 2 == 0) {
        return true;
    }

    // Check for pairs of numbers where the sum is divisible by k
    for (int i = 1; i <= k/2; ++i) {
        if (remainders[i] != remainders[k - i]) {
            return false;
        }
    }

    return true;
