public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a parent list to build the tree
    List<Integer>[] parentList = new List[n];
    for (int i = 0; i < parentList.length; i++) {
        parentList[i] = new ArrayList<>();
    }

    // Build the tree
    for (int[] edge : edges) {
        parentList[edge[1]].add(edge[0]);
    }

    // Initialize a set to store the path from the root to any node that can collect apples
    Set<Integer> path = new HashSet<>();
    boolean[] visited = new boolean[n];
    visited[0] = true;
    path.add(0);

    // Traverse the tree to find the minimum time required to collect all apples
    dfs(0, path, visited, hasApple);

    // Calculate the minimum time by subtracting 2 from each collected node and summing them up
    int[] collected = new int[n];
    for (Integer node : path) {
        collected[node] = 1;
    }
    int minTime = 0;
    for (int i = 0, j = 1; i < n; i++, j++) {
        if (i != j && collected[j]) {
            minTime += 2;
        }
    }
    return minTime;
}

// Helper method to perform a depth-first search to build the tree and collect apples
private void dfs(int node, Set<Integer> path, boolean[] visited, boolean[] hasApple) {
    for (int child : parentList[node]) {
        if (!visited[child]) {
            visited[child] = true;
            path.add(child);
            dfs(child, path, visited, hasApple);
            path.remove(child);
        }
    }
    if (hasApple[node]) {
        path.add(node);
    }
}
