import java.util.*;

class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] edge : edges) {
            graph.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
            graph.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
        }

        boolean[] visited = new boolean[n];
        int[] appleTime = new int[n];
        appleTime[0] = minTime BuildingTree(graph, visited, 0, n, hasApple, appleTime);
        return appleTime[0];
    }

    private int minTimeBuildingTree(Map<Integer, List<Integer>> graph, boolean[] visited, int prev, int n, boolean[] hasApple, int[] time) {
        visited[prev] = true;
        int timeSum = 0;

        for (int adj : graph.getOrDefault(prev, new ArrayList<>())) {
            if (!visited[adj]) {
                timeSum += minTimeBuildingTree(graph, visited, adj, n, hasApple, time);
            }
        }

        if (timeSum > 0 || (prev < 0 && hasApple[prev])) {
            time[prev] = timeSum + 2;
        }

        return time[prev];
    }
}

