import java.util.*;

public class ApplePicker {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Build the adjacency list representation of the tree
        List<List<Integer>> adjList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjList.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adjList.get(u).add(v);
            adjList.get(v).add(u);
        }

        // Perform DFS to calculate the minimum time required
        boolean[] visited = new boolean[n];
        int[] appleTime = new int[n];
        visited[0] = true;
        appleTime[0] = 0;
        dfs(0, n, edges, hasApple, visited, appleTime);

        // Count the total time
        int totalTime = 0;
        for (int time : appleTime) {
            totalTime += time;
        }

        return totalTime;
    }

    private void dfs(int node, int n, int[][] edges, boolean[] hasApple, boolean[] visited, int[] appleTime) {
        for (int child : adjList.get(node)) {
            if (!visited[child]) {
                visited[child] = true;
                appleTime[child] = appleTime[node] + 2; // Add 2 to account for the self-hop
                dfs(child, n, edges, hasApple, visited, appleTime);
            } else if (hasApple[child]) {
                appleTime[child] = appleTime[node] + 2; // Add 2 to account for the self-hop
            }
        }
    }

    public static void main(String[] args) {
        ApplePicker app = new ApplePicker();
        int[][] edges1 = {{0, 1}, {0, 2}, {1, 4}, {1, 5}, {2, 3}, {2, 6}};
