public String sortString(String s) {
    if (s == null || s.isEmpty()) return "";

    StringBuilder result = new StringBuilder();
    int[] count = new int[256];

    // Count the occurrences of each character
    for (char c : s.toCharArray()) {
        count[c]++;
    }

    PriorityQueue<Character> minHeap = new PriorityQueue<>((a, b) -> count[a] == count[b] ? a - b : count[a] - count[b]);
    PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> count[a] == count[b] ? a - b : count[b] - count[a]);

    // Add characters to min and max heaps
    for (int i = 0; i < 256; i++) {
        if (count[i] > 0) {
            minHeap.offer((char) i);
            maxHeap.offer((char) i);
        }
    }

    // Sort the string
    while (!minHeap.isEmpty()) {
        if (maxHeap.isEmpty() || count[minHeap.peek()] >= count[maxHeap.peek()]) {
            result.append(minHeap.poll());
        } else {
            result.append(maxHeap.poll());
        }
        count[minHeap.peek()]--;
        count[maxHeap.peek()]--;
    }

    return result.toString();
}
