public String sortString(String s) {
    if (s == null || s.isEmpty()) return s;

    StringBuilder result = new StringBuilder();
    boolean[] picked = new boolean[s.length()];

    while (!s.isEmpty()) {
        // Step 1 and 2: Pick the smallest character
        int smallestIndex = findSmallest(s, picked);
        if (smallestIndex != -1) {
            result.append(s.charAt(smallestIndex));
            picked[smallestIndex] = true;
        } else {
            // If no smallest character left, break the loop
            break;
        }

        // Skip the same character
        skipChar(s, picked);

        // Step 3 and 4: Pick the largest character
        int largestIndex = findLargest(s, picked);
        if (largestIndex != -1) {
            result.append(s.charAt(largestIndex));
            picked[largestIndex] = true;
        } else {
            // If no largest character left, break the loop
            break;
        }

        // Skip the same character
        skipChar(s, picked);
    }

    return result.toString();
}

private int findSmallest(String s, boolean[] picked) {
    int smallestIndex = -1;
    for (int i = 0; i < s.length(); i++) {
        if (!picked[i] && (smallestIndex == -1 || s.charAt(i) < s.charAt(smallestIndex))) {
            smallestIndex = i;
        }
    }
    return smallestIndex;
}

private int findLargest(String s, boolean[] picked) {
    int largestIndex = -1;
    for (int i = s.length() - 1; i >= 0; i--) {
        if (!picked[i] && (largestIndex == -1 || s.charAt(i) > s.charAt(largestIndex))) {
            largestIndex = i;
        }
    }
    return largestIndex;
}

private void skipChar(String s, boolean[] picked) {
    for (int i = 0; i < s.length(); i++) {
        if (!picked[i] && s.charAt(i) >= s.charAt(smallestIndex)) {
            picked[i] = true;
            return;
