public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    int n = s.length();
    int[] charCount = new int[26]; // Array to keep track of character counts

    // Count the occurrences of each character in the string
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    // Sort characters in ascending order
    PriorityQueue<Character> queue = Arrays.stream(charCount)
                                       .boxed()
                                       .sorted(Integer::compare)
                                       .mapToObj(Integer::valueOf)
                                       .collect(Collectors.toCollection(PriorityQueue::new));

    // Start sorting
    while (!queue.isEmpty()) {
        char currentChar = queue.poll();
        int count = charCount[currentChar - 'a'];

        while (count > 0) {
            result.append(currentChar);
            count--;
        }

        // Adjust counts for characters greater than the current
        for (int i = currentChar - 'a' + 1; i < 26; i++) {
            char nextChar = (char) (i + 'a');
            if (charCount[nextChar - 'a'] > 0) {
                queue.add(nextChar);
                charCount[nextChar - 'a']--;
            } else {
                break;
            }
        }

        // Adjust counts for characters less than the current
        for (int i = currentChar - 'a' - 1; i >= 0; i--) {
            char nextChar = (char) (i + 'a');
            if (charCount[nextChar - 'a'] > 0) {
                queue.add(nextChar);
                charCount[nextChar - 'a']--;
            } else {
                break;
            }
        }
    }

    return result.toString();
}
