public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    if (total % 2 != 0) {
        return false;
    }
    double targetSum = total / 2;

    Integer[][] memo = new Integer[n][n / 2 + 1];
    for (int[] row : memo) {
        Arrays.fill(row, -1);
    }

    return dfs(nums, 0, targetSum / 2, memo);
}

private boolean dfs(int[] nums, int start, int target, Integer[][] memo) {
    if (target < 0 || start >= nums.length || nums[start] > target) {
        return false;
    }
    if (memo[start][target] != null) {
        return memo[start][target] == 1;
    }
    if (start == nums.length - 1 && target == nums[start]) {
        return true;
    }
    boolean result = dfs(nums, start + 1, target - nums[start], memo) || dfs(nums, start + 1, target, memo);
    memo[start][target] = result ? 1 : 0;
    return result;
}
