public boolean hasAllCodes(String s, int k) {
    // Edge case check
    if (s.length() < k) {
        return false;
    }

    // Create a boolean array to keep track of the frequency of each substring of length k
    boolean[] freq = new boolean[1 << k];
    int usedBits = 0;

    // Iterate through the string
    for (int i = 0; i <= s.length() - k; i++) {
        int sub = 0;
        // Extract the substring of length k starting from position i
        for (int j = i; j < i + k; j++) {
            sub <<= 1;
            sub |= s.charAt(j) - '0'; // Convert char to int and shift left
        }
        // Check if the substring has already been used
        if (freq[sub]) {
            return false;
        }
        // Mark the substring as used
        freq[sub] = true;
    }

    // Check if all possible substrings of length k have been used
    for (boolean bit : freq) {
        if (!bit) {
            return false;
        }
    }

    return true;
}
