public int minInsertions(String s) {
    int balance = 0;
    int insertionsNeeded = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else {  // c == ')'
            balance--;
            if (balance < 0) {
                // If there's a closing brace without a corresponding opening brace,
                // we need to insert an opening brace.
                insertionsNeeded++;
                balance++;
            }
        }
    }

    // After processing all characters, there may still be opening braces left.
    return insertionsNeeded + balance;
}
