public int maxAbsoluteSum(int[] nums) {
    int n = nums.length;
    if (n == 0) return 0;

    int maxSum = nums[0];
    int minSum = nums[0];

    int result = 0;

    for (int i = 1; i < n; i++) {
        int currentMax = Math.max(nums[i], nums[i] + maxSum);
        int currentMin = Math.min(nums[i], nums[i] + minSum);

        maxSum = currentMax;
        minSum = currentMin;

        result = Math.max(result, Math.abs(maxSum - minSum));
    }

    return result;
}
