import java.lang.Math;

public class Main {
    public static int kthFactor(int n, int k) {
        // Validate input
        if (n <= 0 || k <= 0 || k > n) {
            throw new IllegalArgumentException("Invalid input");
        }

        // Calculate the maximum potential factor
        int maxFactor = (int) Math.sqrt(n);
        int nextFactor = 2;

        // Find the kth factor
        for (int i = 1; i <= maxFactor; i++) {
            int factor = i;
            if (n % factor == 0) {
                // Check if it's the kth factor
                if ((k % 2 == 0 && factor == maxFactor) || (k % 2 != 0 && factor == nextFactor)) {
                    return factor;
                }
                k -= (i == factor) ? 1 : 2; // Adjust k for next iteration
            }
            nextFactor += 2; // Reasonable factor increment
        }

        return -1; // Failed to find the kth factor
    }

    public static void main(String[] args) {
        System.out.println(kthFactor(12, 3)); // Expected output: 3
        System.out.println(kthFactor(7, 2));  // Expected output: 7
        System.out.println(kthFactor(4, 4));  // Expected output: -1
    }
}
