public static double calculateProbability(int n) {
    // Check if the input is less than or equal to 1, which doesn't make sense in this context
    if (n <= 1) {
        throw new IllegalArgumentException("Input must be greater than 1");
    }

    // The recurrence relation for the problem
    double[][] dp = new double[2][n + 1];
    dp[1][1] = 0.5; // If there's only one passenger, the probability is 0.5 (arbitrary choice)

    for (int i = 2; i <= 100000; i++) {
        dp[1][i] = 0.5; // Base case: probability for 2 or more passengers is 0.5
        dp[0][i] = dp[1][i] * 0.5 + countSameAndOppositeSeats(dp, n, i - 1); // Recurrence relation
    }

    return dp[0][n]; // The last entry gives the probability for n passengers
}

// Function to count the number of same and opposite seats among the given conditions
private static double countSameAndOppositeSeats(double[][] dp, int lastK, int index) {
    int a = countSameSeatsdp, b = countOppositeSeatsdp;
    if (index > 0) {
        a += dp[0][index - 1];
        b += dp[1][index - 1];
    }
    return a + b;
}

