private static int countSameSeats(double[][] dp, int lastK) {
    return (int) dp[lastK][lastK];
}

// Function to count the number of opposite seats among the given conditions
private static int countOppositeSeats(double[][] dp, int lastK) {
    return (int) dp[1][lastK];
}
