public static double calculateProbability(int n) {
    if (n <= 1) {
        throw new IllegalArgumentException("n must be greater than 1");
    }
    if (n == 2) {
        return 0.5;
    }

    // Create an array to store intermediate results
    double[] dp = new double[n + 1];
    dp[0] = 0.0;
    dp[1] = 1.0;
    dp[2] = 0.5;

    // Calculate the probability for each number of passengers
    for (int i = 3; i <= n; i++) {
        dp[i] = 1 - dp[i - 1];
    }

    // The last passenger will be in their own seat if there's only one passenger
    if (n == 1) {
        return 1.0;
    }

    // Return the probability of the last passenger sitting in their own seat
    return dp[n];
