private static boolean isSteppingNumber(int num) {
    if (num <= 9) {
        return true;
    }
    int prevDigit = num % 10;
    num /= 10;
    while (num > 0) {
        int currentDigit = num % 10;
        if (Math.abs(currentDigit - prevDigit) != 1) {
            return false;
        }
        prevDigit = currentDigit;
        num /= 10;
    }
    return true;
}
