import java.lang.Math;

public class PowerOfTwoChecker {
    /**
     * Checks if the given integer n is a power of two.
     *
     * @param n The integer to check.
     * @return true if n is a power of two, false otherwise.
     */
    public static boolean isPowerOfTwo(int n) {
        // Check if n is less than 1, as 0 and negative numbers cannot be powers of two
        if (n < 1) {
            return false;
        }
        // Calculate log base 2 of n and compare it to the floor value of log base 2 of n
        return (int) Math.round(Math.log(n) / Math.log(2)) == (int) Math.log(n);
    }

    // Test the isPowerOfTwo method with provided data points
    public static void main(String[] args) {
        System.out.println(isPowerOfTwo(1)); // true
        System.out.println(isPowerOfTwo(16)); // true
        System.out.println(isPowerOfTwo(3)); // false
        System.out.println(isPowerOfTwo(4)); // true
        System.out.println(isPowerOfTwo(5)); // false
    }
}
