        return 0;
    }

    int maxLen = 0;

    // Store the count of 1s in each row for horizontal lines
    int[] rowCount = new int[mat.length];
    // Store the count of 1s in each column for vertical lines
    int[] colCount = new int[mat[0].length];

    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
               rowCount[i]++;
                colCount[j]++;
                // Update the maximum line length in both directions
                int maxInRow = Math.max(maxLineRL(rowCount[i]), maxLen);
                int maxInCol = Math.max(maxLineRL(colCount[j]), maxLen);
                maxLen = Math.max(maxLineAR(rowCount[j]), maxLen);
                maxLen = Math.max(maxLineAD(rowCount[i], colCount[j]), maxLen);
            }
            maxLen = Math.max(maxInRow, maxInCol);
        }
    }
    return maxLen;
}

private static int maxLineRL(int count) {
    int maxLen = 0, tmpLen = 0;
    for (int i = count; i >= 0; i--) {
        tmpLen += i;
        maxLen = Math.max(maxLen, tmpLen);
    }
    return maxLen;
}

private static int maxLineAR(int rowCount[], int colCount[]) {
    int maxLine = 0;
    for (int k = 0; k < rowCount.length; k++) {
        int tmpLen = rowCount[k] + colCount[k];
        if (tmpLen > maxLine) {
            maxLine = tmpLen;
        }
    }
    return maxLine;
}

private static int maxLineAD(int rowCount[], int colCount[]) {
    int maxLine = 0;
    for (int j = 0, k = colCount.length - 1; k >= 0; j++, k--) {
        int tmpLen = rowCount[j] + colCount[k];
        if (tmpLen > maxLine) {
            maxLine = tmpLen;
        }
    }
    return maxLine;
