import java.util.HashSet;
import java.util.List;
import java.util.Set;

public static int squarePermutations(int[] A) {
    if (A == null || A.length <= 1) return 0; // Base case: array is null or has only one element

    int n = A.length;
    List<Integer> perm = new ArrayList<>();
    Set<Integer> seen = new HashSet<>();

    List<Integer> result = new ArrayList<>();
    permHelper(A, n, perm, seen, result);

    return result.size();
}

private static void permHelper(int[] A, int n, List<Integer> perm, Set<Integer> seen, List<Integer> result) {
    if (perm.size() == n) {
        result.add(new ArrayList<>(perm));
        return;
    }

    for (int i = 0; i < n; i++) {
        if (seen.contains(A[i])) continue;
        seen.add(A[i]);
