public class SquarePermutationCount {

    /**
     * Calculates the number of square permutations of a non-negative integer array.
     * A square permutation is defined as an array where the sum of each pair of adjacent elements is a perfect square.
     *
     * @param A the input non-negative integer array
     * @return the number of square permutations
     * @throws IllegalArgumentException if the input array is empty
     */
    public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            throw new IllegalArgumentException("Array must not be null or empty");
        }

        int count = 0;
        int n = A.length;

        // Helper method to check if the given permutation is a square permutation
        boolean isSquarePermutation(int[] perm) {
            for (int i = 0; i < n - 1; i++) {
                long sum = (long) perm[i] + perm[i + 1];
                if (!isPerfectSquare(sum)) {
                    return false;
                }
            }
            return true;
        }

        // Generate all permutations of the array
        for (int i = 0; i < n; i++) {
            int temp = A[i];
            for (int j = i + 1; j < n; j++) {
                int[] tempArray = new int[n];
                System.arraycopy(A, 0, tempArray, 0, i);
                tempArray[i] = A[j];
                System.arraycopy(A, i + 1, tempArray, i + 1, n - i - 1);
                tempArray[n - 1] = temp;
                count += isSquarePermutation(tempArray) ? 1 : 0;
            }
        }

        return count;
    }

    // Helper method to check if a number is a perfect square
    private static boolean isPerfectSquare(long number) {
        long s = (long) Math.sqrt(number);
        return s * s == number;
    }

    // Check function to verify the correctness of the generated function
    public static void main(String[] args) {
        System.out.println(squarePermutations(new int[]{1, 17, 8}));  // Output: 2
        System.out.println(squarePermutations(new int[]{2, 2, 2}));  // Output: 1
    }
}
