import java.util.HashSet;
import java.util.Arrays;
import java.util.Set;

public class PermutationsChecker {

    /**
     * Check if a number is a perfect square.
     *
     * @param number The number to check.
     * @return true if the number is a perfect square, false otherwise.
     */
    private static boolean isPerfectSquare(int number) {
        int sqrt = (int) Math.sqrt(number);
        return sqrt * sqrt == number;
    }

    /**
     * Swap two elements in an array.
     *
     * @param array The array in which elements will be swapped.
     * @param index1 The index of the first element to swap.
     * @param index2 The index of the second element to swap.
     */
    private static void swap(int[] array, int index1, int index2) {
        int temp = array[index1];
        array[index1] = array[index2];
        array[index2] = temp;
    }

    /**
     * Generate all permutations of the array and count the square permutations.
     *
     * @param array The input non-negative integer array.
     * @param length The length of the array.
     * @param perm The current permutation being constructed.
     * @param correctCount The counter for valid permutations.
     * @return The count of valid square permutations.
     */
    private static int countSquarePermutations(int[] array, int length, int[] perm, int correctCount) {
        if (length == 2) {
            if (isPerfectSquare(array[0] + array[1])) {
                correctCount++;
            }
            return correctCount;
        }

        for (int i = length - 1; i >= 0; i--) {
            swap(array, length - 1, i);
            perm[length - 1] = array[length - 1];
            countSquarePermutations(array, length - 1, perm, correctCount);
            swap(array, length - 1, i);
        }

        return correctCount;
    }

    /**
     * Find the number of square permutations of the array A.
     *
     * @param A The input non-negative integer array.
     * @return The number of square permutations of A.
     */
    public static int squarePermutations(int[] A) {
        int n = A.length;
        int[] perm = new int[n];
        int correctCount = 0;
        Arrays.sort(A); // Ensure elements in ascending order
        correctCount = countSquarePermutations(A, n, perm, correctCount);
        return correctCount;
    }
}
