        return -1;
    }

    int[] digits = new int[10];
    int originalDigits = n;
    int numberOfDigits = 0;

    // Count the occurrences of each digit in the original number
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
        numberOfDigits++;
    }

    // Start with the largest digit and work way down to find the smallest possible rearrangement
    for (int i = 9; i >= 0; i--) {
        if (digits[i] > 0) {
            int temp = originalDigits % 10;
            originalDigits /= 10;

            // Swap the current digit with the largest possible digit that is less than it
            while (digits[i] == 0) {
                i--;
            }

            int temp2 = i % 10;
            i /= 10;
            digits[i]++;
            temp += temp2;

            // Sort the remaining digits to form the smallest possible number
            selectionSort(digits, i + 1, 9);

            // The smallest rearranged integer is formed by concatenating the remaining digits
            return temp;
        }
    }

    return -1;
}

private static void selectionSort(int[] nums, int left, int right) {
    for (int i = left; i <= right; i++) {
        int minIndex = i;
        for (int j = i + 1; j <= right; j++) {
            if (nums[j] < nums[minIndex]) {
                minIndex = j;
            }
        }
        int temp = nums[i];
        nums[i] = nums[minIndex];
        nums[minIndex] = temp;
    }
