public class CenterSymmetricNumbers {
    public static List<String> centerSymmetricNumbers(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("The length of the center symmetric numbers must be a positive integer.");
        }

        List<String> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String prefix = generatePrefix(i);
            result.add(prefix + new StringBuilder(prefix).reverse().toString());
        }
        return result;
    }

    private static String generatePrefix(int n) {
        int halfLength = n / 2;
        String prefix = "";
        char[] prefixArray = new char[halfLength];
        for (int i = 0; i < halfLength; i++) {
            int remainder = i % 2;
            switch (remainder) {
                case 0:
                    prefixArray[i] = '0';
                    break;
                case 1:
                    prefixArray[i] = '1';
                    break;
            }
        }
        return String.valueOf(prefixArray);
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: [11, 69, 88, 96]
        System.out.println(centerSymmetricNumbers(1)); // Output: [0, 1, 8]
    }
