public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();

    if (n < 1) {
        throw new IllegalArgumentException("Input must be greater or equal to 1");
    }

    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }

    return result;
}

private void dfs(int current, int limit, List<Integer> result) {
    if (current * 10 > limit) {
        return;
    }

    result.add(current);
    for (int i = 0; i < 10; i++) {
        int next = current * 10 + i;
        if (next <= limit) {
            dfs(next, limit, result);
        }
    }
}
