public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();

    // Helper method to perform depth-first search recursively
    public void dfs(int num) {
        if (num > n) return;

        result.add(num);

        // Explore the next digits by incrementing the least significant digit
        if (num * 10 <= n) {
            dfs(num * 10);
        }

        // Do not explore more significant digits if num ends in 9
        if (num % 10 != 9) {
            dfs(num + 1);
        }
    }

    dfs(1);
    return result;
}
