    if (n % Math.sqrt(n) == 0) return 1;

    int[] dp = new int[n + 1];
    Arrays.fill(dp, n + 1);
    dp[0] = 0; // Base case

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int value = (int) Math.sqrt(i) + dp[i - (j * j)];
            if (value < dp[i]) dp[i] = value;
        }
    }
    return dp[n];
