import java.math.BigInteger;

public static int minPerfectSquareSum(int n) {
    // Handle the special case for 0
    if (n == 0) {
        return 0;
    }

    // Array to store the minimum number of perfect square numbers for each number up to n
    BigInteger[] dp = new BigInteger[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = BigInteger.valueOf(Integer.MAX_VALUE);
    }

    // Base case: the minimum number of perfect square numbers for 0 is 0
    dp[0] = BigInteger.ZERO;

    // Loop through all perfect squares
    for (int i = 1; i * i <= n; i++) {
        BigInteger base = BigInteger.valueOf(i * i);
        for (int j = i * i; j <= n; j++) {
            dp[j] = dp[j].min(dp[j - base].add(BigInteger.ONE));
        }
    }

    // Return the minimum number of perfect square numbers for n
    return dp[n].intValue();
}
