    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string is null or empty");
    }

    StringBuilder result = new StringBuilder();
    int wordStart = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ' ') {
            // Reverse the current word
            reverseSubstring(result, wordStart, i);
            result.append(' '); // Append the space
            wordStart = i + 1; // Reset starting index of the next word
        }
    }

    // Reverse the last word
    reverseSubstring(result, wordStart, s.length());

    return result.toString();
}

private static void reverseSubstring(StringBuilder sb, int start, int end) {
    while (start < end) {
        char temp = sb.charAt(start);
        sb.setCharAt(start, sb.charAt(end - 1));
        sb.setCharAt(end - 1, temp);
        start++;
        end--;
    }
}
